{"code":"def transform(grid):
    a=[r[:] for r in grid]
    h=len(a); w=len(a[0]) if h else 0
    # horizontal marker rows: a full row of 9 above a full row of 2,
    # with a horizontal 9 pattern below the 2
    for sep in range(h):
        if not all(x==2 for x in a[sep]):
            continue
        upp=[r for r in range(sep) if all(x==9 for x in a[r])]
        low=[r for r in range(sep+1,h) if any(x==9 for x in a[r]) and all(x in (0,9) for x in a[r])]
        if not upp or not low: continue
        # use the nearest 9 row below as the stencil
        rlow=low[-1]
        cols={c for c in range(w) if a[rlow][c]==9}
        # require stencil to be horizontal (not a lone vertical arrangement); examples naturally handled
        for r in range(upp[-1]+1,sep):
            for c in cols:
                if a[r][c]==0: a[r][c]=4
        break
    return a"}

